    def test_skip_build_requires_matching_source_and_finished_executable(self):
        build = self.root / "build"
        build.mkdir()
        binary = build / "mixxx"
        binary.write_text("#!/bin/sh\nexit 0\n")
        binary.chmod(0o755)
        cache = build / "CMakeCache.txt"
        cache.write_text(f"CMAKE_HOME_DIRECTORY:INTERNAL={self.root}\n")
        installer.existing_build(build, self.root)
        with self.assertRaises(ValueError):
            installer.existing_build(build, self.root / "other source")
        binary.unlink()
        with self.assertRaises(ValueError):
            installer.existing_build(build, self.root)

    def test_starter_passes_paths_and_arguments_without_shell_expansion(self):
        prefix = self.root / 'Mixxx\'s $local % "quoted" \\ build'
        binary = prefix / "bin/mixxx"
        captured = self.root / "arguments.txt"
        installer.write_atomic(
            binary,
            "#!/bin/sh\nprintf '%s\\n' \"$@\" > "
            + shlex.quote(str(captured))
            + "\n",
            0o755,
        )
        profile = self.root / "profile's $settings"
        link = installer.install_launchers(
            prefix, profile, self.root / "bin", self.root / "data"
        )
        subprocess.run([str(link), "--log-level", "debug"], check=True)
        self.assertEqual(
            captured.read_text().splitlines(),
            [
                "--resource-path",
                str(prefix / "share/mixxx"),
                "--settings-path",
                str(profile),
                "--log-level",
                "debug",
            ],
        )
        installer.install_launchers(
            prefix, profile, self.root / "bin", self.root / "data"
        )
        desktop = (
            self.root
            / "data/applications/org.mixxx.Mixxx.BpmImprovements.desktop"
        ).read_text()
        self.assertIn("%%", desktop)
        if installer.shutil.which("desktop-file-validate"):
            subprocess.run(
                [
                    "desktop-file-validate",
                    str(
                        self.root
                        / "data/applications"
                        / "org.mixxx.Mixxx.BpmImprovements.desktop"
                    ),
                ],
                check=True,
            )
        other = self.root / "other-bin/mixxx-bpm-improvements"
        other.parent.mkdir()
        other.write_text("unrelated")
        with self.assertRaises(ValueError):
            installer.install_launchers(
                prefix, profile, other.parent, self.root / "data"
            )
        self.assertEqual(other.read_text(), "unrelated")

