    def test_build_and_install_modes_preserve_the_selected_profile(self):
        source = self.sources(self.root / "source")
        build = self.root / "build"
        build.mkdir()
        (build / "CMakeCache.txt").write_text(
            f"CMAKE_HOME_DIRECTORY:INTERNAL={source}\n"
            f"CMAKE_INSTALL_PREFIX:PATH={self.root / 'prefix'}\n"
            + "".join(
                f"{key}:PATH={value}\n"
                for key, value in installer.INSTALL_LAYOUT.items()
            )
            + "INSTALL_USER_UDEV_RULES:BOOL=OFF\n"
        )
        installer.write_atomic(build / "mixxx", "#!/bin/sh\nexit 0\n", 0o755)
        profile = self.root / "existing profile"
        profile.mkdir()
        config = profile / "mixxx.cfg"
        original = (
            "[BPM]\ntempo_mode 2\nBPMDetectionEnabled 0\n"
            "[Vamp]\nAnalyserBeatPluginID qm-tempotracker:0\n"
            "[Library]\nDirectory\tMusic with spaces\n"
        )
        config.write_text(original)
        for mode, skip in (
            ("build", False),
            ("install", False),
            ("build", True),
            ("install", True),
        ):
            with self.subTest(mode=mode, skip=skip):
                self.check_mode(mode, skip, source, build, profile, original)

    def check_mode(self, mode, skip, source, build, profile, original):
        with contextlib.ExitStack() as stack:
            stack.enter_context(
                patch.dict(
                    installer.os.environ,
                    {"XDG_DATA_HOME": str(self.root / "data")},
                )
            )
            stack.enter_context(
                patch.object(installer.os, "geteuid", return_value=1000)
            )
            stack.enter_context(
                patch.object(
                    installer.shutil, "which", return_value="tool"
                )
            )
            stack.enter_context(
                patch.object(
                    installer, "compile_budget", return_value=(1024, 1)
                )
            )
            stack.enter_context(
                patch.object(
                    installer,
                    "build_command",
                    return_value=[
                        "cmake", "--build", build, "--parallel", 1
                    ],
                )
            )
            configure = stack.enter_context(
                patch.object(installer, "configure_build")
            )
            calls = stack.enter_context(patch.object(installer, "run"))
            launchers = stack.enter_context(
                patch.object(installer, "install_launchers")
            )
            output = stack.enter_context(
                contextlib.redirect_stdout(io.StringIO())
            )
            args = [
                "--mode", mode,
                "--source-dir", str(source),
                "--build-dir", str(build),
                "--profile", str(profile),
                "--prefix", str(self.root / "prefix"),
                "--bin-dir", str(self.root / "bin"),
            ]
            if skip:
                args.append("--skip-build")
            installer.main(args)
            commands = [call.args[0] for call in calls.call_args_list]
            self.assertEqual(
                sum("--install" in command for command in commands),
                int(mode == "install"),
            )
            self.assertEqual(
                sum("--build" in command for command in commands),
                int(not skip),
            )
            self.assertEqual(launchers.call_count, int(mode == "install"))
            self.assertEqual(configure.call_count, int(not skip))
            self.assertEqual((profile / "mixxx.cfg").read_text(), original)
            self.assertNotIn("BeatThis", output.getvalue())
            self.assertNotIn("pip", repr(commands))
            self.assertNotIn("sudo", repr(commands))

